import java.io.File;
import java.nio.file.Path;
import java.nio.file.Paths;

public class ImportingUtilities {

    // other methods

    /**
     * Allocates a unique file inside {@code dir} using {@code name} as the base.
     * <p>
     * The method validates that the resulting file resides within {@code dir}
     * to prevent directory‑traversal attacks. It also normalises the path,
     * removes query parameters, and ensures that the file name does not
     * escape the target directory.
     *
     * @param dir  the target directory (must not be {@code null})
     * @param name the desired file name (may contain query parameters)
     * @return a {@link File} instance that does not yet exist
     * @throws IllegalArgumentException if {@code dir} or {@code name} is {@code null},
     *                                  or if the resolved path would escape {@code dir}
     */
    static public File allocateFile(File dir, String name) {
        if (dir == null) {
            throw new IllegalArgumentException("Target directory cannot be null");
        }
        if (name == null) {
            throw new IllegalArgumentException("File name cannot be null");
        }

        // Strip query string if present
        int q = name.indexOf('?');
        if (q > 0) {
            name = name.substring(0, q);
        }

        // Resolve the candidate file path
        File file = new File(dir, name);

        // Normalise both paths to absolute form and verify containment
        Path dirPath = dir.toPath().toAbsolutePath().normalize();
        Path filePath = file.toPath().toAbsolutePath().normalize();

        if (!filePath.startsWith(dirPath)) {
            throw new IllegalArgumentException(
                "Attempted to create a file outside the target directory: " + filePath);
        }

        // Generate a unique filename if necessary
        int dot = name.indexOf('.');
        String prefix = dot < 0 ? name : name.substring(0, dot);
        String suffix = dot < 0 ? "" : name.substring(dot);
        int index = 2;
        while (file.exists()) {
            file = new File(dir, prefix + "-" + index++ + suffix);
            filePath = file.toPath().toAbsolutePath().normalize();
            if (!filePath.startsWith(dirPath)) {
                throw new IllegalArgumentException(
                    "Generated file path escapes the target directory: " + filePath);
            }
        }

        // Ensure the parent directory exists
        File parent = file.getParentFile();
        if (parent != null && !parent.exists()) {
            if (!parent.mkdirs()) {
                throw new RuntimeException("Failed to create directories: " + parent);
            }
        }

        return file;
    }

    // other methods
}
