        int i = 0;
        while (i < path.length() && path.charAt(i) == '/') {
            i++;
        }

        // Remaining part after stripping leading slashes
        final String remaining = (i == path.length()) ? "" : path.substring(i);

        // Preserve empty path (e.g., "/")
        if (remaining.isEmpty()) {
            return "";
