     * for script injection or other malicious payloads.
     */
    private static final Pattern LOCALE_PATTERN =
            Pattern.compile("^[a-zA-Z]{2,3}(_[a-zA-Z]{2})?$");

    /* --------------------------------------------------------------------- */
    /*  Core interceptor logic                                               */
    /* --------------------------------------------------------------------- */

    /**
     * Creates a {@link Locale} object from the request param, which might
     * already be a {@link Locale} or a {@link String}.  The method validates
     * the string representation against a strict whitelist to prevent
     * injection of malicious content.
     *
     * @param requestedLocale the parameter from the request
     * @return the {@link Locale} if the input is valid; otherwise {@code null}
     */
    protected Locale getLocaleFromParam(Object requestedLocale) {
        Locale locale = null;

        if (requestedLocale == null) {
            return null;
        }

        if (requestedLocale instanceof Locale) {
            locale = (Locale) requestedLocale;
        } else if (requestedLocale instanceof String) {
            String localeStr = ((String) requestedLocale).trim();

            if (!localeStr.isEmpty() && LOCALE_PATTERN.matcher(localeStr).matches()) {
                // Convert to lower‑case language and upper‑case country to match
                // Locale conventions (e.g., "en_us" → "en_US").
                String[] parts = localeStr.split("_");
                String language = parts[0].toLowerCase();
                String country = parts.length > 1 ? parts[1].toUpperCase() : "";
                locale = LocalizedTextUtil.localeFromString(language + (country.isEmpty() ? "" : "_" + country), null);
            } else {
                LOG.warn("Invalid locale format received: '{}'. Ignoring request locale.", localeStr);
            }
        } else {
            LOG.warn("Unsupported type for locale conversion: {}. Expected String or Locale.",
                    requestedLocale.getClass().getName());
        }

        if (locale != null) {
            LOG.debug("Applied request locale: {}", locale);
        }

        return locale;
    }

