            Arrays.asList(
                    String.class,
                    Integer.class,
                    Long.class,
                    Double.class,
                    Float.class,
                    Short.class,
                    Byte.class,
                    Boolean.class,
                    Character.class,
                    BigDecimal.class,
                    BigInteger.class,
                    Date.class,
                    java.sql.Date.class,
                    java.time.LocalDate.class,
