     * @return {@code true} if the class is permitted, {@code false} otherwise
     */
    private static boolean isAllowedComponent(Class<?> cls) {
        if (cls == null) {
            return false;
        }
        if (cls.isPrimitive() || cls.isEnum()) {
            return true;
