import org.apache.camel.Exchange;
import org.apache.camel.Converter;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.xml.sax.InputSource;
import org.xml.sax.SAXException;
import org.xml.sax.XMLReader;

@Converter
public class XmlConverter {

    private static final Logger LOG = LoggerFactory.getLogger(XmlConverter.class);

    // --------------------------------------------------------------------
    // XML conversion utilities
    // --------------------------------------------------------------------

    /**
     * Converts a {@link StreamSource} into a {@link SAXSource} while protecting
     * against XML External Entity (XXE) attacks. The method explicitly disables
     * all forms of external entity resolution and DTD processing.
     *
     * @param source   the source XML stream
     * @param exchange optional Camel exchange that may contain a pre‑configured
     *                 {@link SAXParserFactory}
     * @return a secure {@link SAXSource}
     * @throws SAXException if the parser cannot be created or configured
     */
    @Converter
    public SAXSource toSAXSourceFromStream(StreamSource source, Exchange exchange) throws SAXException {
        // Build an InputSource from the StreamSource
        InputSource inputSource = (source.getReader() != null)
                ? new InputSource(source.getReader())
                : new InputSource(source.getInputStream());

        inputSource.setSystemId(source.getSystemId());
        inputSource.setPublicId(source.getPublicId());

        XMLReader xmlReader = null;
        SAXParserFactory factory = null;

        try {
            // Reuse a factory from the exchange if available
            if (exchange != null) {
                factory = exchange.getProperty(Exchange.SAXPARSER_FACTORY, SAXParserFactory.class);
            }

            // Create a new factory if none was supplied
            if (factory == null) {
                factory = SAXParserFactory.newInstance();

                // Enable secure processing
                try {
                    factory.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);
                } catch (Exception e) {
                    LOG.warn("SAXParserFactory does not support FEATURE_SECURE_PROCESSING: {}", e.toString());
                }

                // Disable all external entity resolution
                setFeature(factory, "http://xml.org/sax/features/external-general-entities", false);
                setFeature(factory, "http://xml.org/sax/features/external-parameter-entities", false);

                // Disallow DOCTYPE declarations entirely
                setFeature(factory, "http://apache.org/xml/features/disallow-doctype-decl", true);

                // Prevent loading of external DTDs and grammars
                setFeature(factory, "http://apache.org/xml/features/nonvalidating/load-external-dtd", false);
                setFeature(factory, "http://apache.org/xml/features/nonvalidating/load-dtd-grammar", false);
            }

            factory.setNamespaceAware(true);

            SAXParser parser = factory.newSAXParser();
            xmlReader = parser.getXMLReader();

            // As an extra safety net, double‑check that the XMLReader itself
            // has the same security features enabled (some parsers expose them
            // separately from the factory).
            setReaderFeature(xmlReader, "http://xml.org/sax/features/external-general-entities", false);
            setReaderFeature(xmlReader, "http://xml.org/sax/features/external-parameter-entities", false);
            setReaderFeature(xmlReader, "http://apache.org/xml/features/disallow-doctype-decl", true);

        } catch (Exception e) {
            LOG.warn("Failed to create a secure SAXParser/XMLReader: {}", e.toString());
            throw new SAXException("Unable to configure secure XML parser", e);
        }

        if (xmlReader == null) {
            throw new SAXException("XMLReader could not be instantiated");
        }

        return new SAXSource(xmlReader, inputSource);
    }

    // --------------------------------------------------------------------
    // Helper methods
    // --------------------------------------------------------------------

    /**
     * Safely sets a feature on a {@link SAXParserFactory}. Any exception is logged
     * as a warning so that the application can continue with a conservative
     * configuration.
     */
    private static void setFeature(SAXParserFactory factory, String name, boolean value) {
        try {
            factory.setFeature(name, value);
        } catch (Exception e) {
            LOG.warn("SAXParserFactory does not support feature {}: {}", name, e.toString());
        }
    }

    /**
     * Safely sets a feature on an {@link XMLReader}. Any exception is logged
     * as a warning so that the application can continue with a conservative
     * configuration.
     */
    private static void setReaderFeature(XMLReader reader, String name, boolean value) {
        try {
            reader.setFeature(name, value);
        } catch (Exception e) {
            LOG.warn("XMLReader does not support feature {}: {}", name, e.toString());
        }
    }

    // --------------------------------------------------------------------
    // Other converter methods would follow here
    // --------------------------------------------------------------------
